#version 450

layout(local_size_x = 1024) in;

layout(std430, binding = 0) buffer DataBuffer {
    uint data[];
};

layout(std430, binding = 1) buffer BlockSumsBuffer {
    uint block_sums[];
};

uniform uint n;

shared uint temp[2048];

void main() {
    uint gid = gl_GlobalInvocationID.x;
    uint lid = gl_LocalInvocationID.x;
    uint bid = gl_WorkGroupID.x;

    uint val = 0;
    if (gid < n) {
        val = data[gid];
    }
    temp[lid] = val;

    // Parallel reduction
    uint stride = 1;
    while (stride <= 512) {
        uint index = (lid + 1) * stride * 2 - 1;
        if (index < 1024) {
            temp[index] += temp[index - stride];
        }
        barrier();
        stride *= 2;
    }

    // Store total sum of the workgroup for the second pass
    if (lid == 1023) {
        block_sums[bid] = temp[1023];
        temp[1023] = 0;
    }
    barrier();

    // Downsweep
    stride = 512;
    while (stride >= 1) {
        uint index = (lid + 1) * stride * 2 - 1;
        if (index < 1024) {
            uint t = temp[index - stride];
            temp[index - stride] = temp[index];
            temp[index] += t;
        }
        barrier();
        stride /= 2;
    }

    if (gid < n) {
        data[gid] = temp[lid];
    }
}

#version 450

layout(local_size_x = 1024) in;

layout(std430, binding = 0) buffer DataBuffer {
    uint data[];
};

layout(std430, binding = 1) buffer BlockSumsBuffer {
    uint block_sums[];
};

uniform uint n;

void main() {
    uint gid = gl_GlobalInvocationID.x;
    uint bid = gl_WorkGroupID.x;
    if (bid > 0 && gid < n) {
        data[gid] += block_sums[bid - 1];
    }
}

#version 450

layout(local_size_x = 1024) in;

layout(std430, binding = 0) buffer BlockSumsBuffer {
    uint block_sums[];
};

uniform uint n_blocks;

shared uint temp[1024];

void main() {
    uint lid = gl_LocalInvocationID.x;

    uint val = 0;
    if (lid < n_blocks) {
        val = block_sums[lid];
    }
    temp[lid] = val;

    uint stride = 1;
    while (stride <= 512) {
        uint index = (lid + 1) * stride * 2 - 1;
        if (index < 1024) {
            temp[index] += temp[index - stride];
        }
        barrier();
        stride *= 2;
    }

    temp[1023] = 0;
    barrier();

    stride = 512;
    while (stride >= 1) {
        uint index = (lid + 1) * stride * 2 - 1;
        if (index < 1024) {
            uint t = temp[index - stride];
            temp[index - stride] = temp[index];
            temp[index] += t;
        }
        barrier();
        stride /= 2;
    }

    if (lid < n_blocks) {
        block_sums[lid] = temp[lid];
    }
}

