func _ready():
    var rd = RenderingServer.create_local_rendering_device()
    var input_path = "res://data/input.txt"
    var file = FileAccess.open(input_path, FileAccess.READ)
    var lines = file.get_as_text().split("\n")
    var n = int(lines[0].strip_edges())
    var data = []
    for i in range(1, n + 1):
        if i < lines.size():
            data.append(int(lines[i].strip_edges()))

    # Prepare buffer
    var data_bytes = PackedInt32Array(data).to_byte_array()
    var data_buffer = rd.storage_buffer_create(data_bytes.size(), data_bytes)

    var num_workgroups = ceil(float(n) / 1024)
    var block_sums_bytes = PackedByteArray()
    block_sums_bytes.resize(num_workgroups * 4)
    var block_sums_buffer = rd.storage_buffer_create(block_sums_bytes.size(), block_sums_bytes)

    var fmt = RDVertexFormat.new()
    var uniform_set = rd.uniform_buffer_create(4, PackedByteArray([n, 0, 0, 0])) # actually uniform needs buffer_create? No uniforms
    # Use push constants or uniform buffers? Let me use uniform buffers for n. Actually push constants are easier. Let me use uniform buffers.

    # Shader 1: workgroup-level exclusive scan + store block sums
    var shader_spv = _compile(rd, "res://scan.glsl")
    var shader = rd.shader_create_from_spirv(shader_spv)

    var uniform0 = RDUniform.new()
    uniform0.uniform_type = RenderingDevice.UNIFORM_TYPE_STORAGE_BUFFER
    uniform0.binding = 0
    uniform0.add_id(data_buffer)
    var uniform1 = RDUniform.new()
    uniform1.uniform_type = RenderingDevice.UNIFORM_TYPE_STORAGE_BUFFER
    uniform1.binding = 1
    uniform1.add_id(block_sums_buffer)

    # Push constant for n
    var push_constant = PackedByteArray([n & 0xff, (n >> 8) & 0xff, (n >> 16) & 0xff, (n >> 24) & 0xff])

    var pipeline = rd.compute_pipeline_create(shader)
    var uniform_set_list = rd.uniform_set_create([uniform0, uniform1], shader, 0)

    var compute_list = rd.compute_list_begin()
    rd.compute_list_bind_compute_pipeline(compute_list, pipeline)
    rd.compute_list_bind_uniform_set(compute_list, uniform_set_list, 0)
    rd.compute_list_set_push_constant(compute_list, push_constant, push_constant.size())
    rd.compute_list_dispatch(compute_list, num_workgroups, 1, 1)
    rd.compute_list_end()
    rd.submit()
    rd.sync()

    # Shader 2: scan the block sums
    var shader2_spv = _compile(rd, "res://scan_small.glsl")
    var shader2 = rd.shader_create_from_spirv(shader2_spv)
    var pipeline2 = rd.compute_pipeline_create(shader2)
    var uniform_set2 = rd.uniform_set_create([uniform1], shader2, 0)
    var push_constant2 = PackedByteArray([num_workgroups & 0xff, 0, 0, 0])

    compute_list = rd.compute_list_begin()
    rd.compute_list_bind_compute_pipeline(compute_list, pipeline2)
    rd.compute_list_bind_uniform_set(compute_list, uniform_set2, 0)
    rd.compute_list_set_push_constant(compute_list, push_constant2, push_constant2.size())
    rd.compute_list_dispatch(compute_list, 1, 1, 1)
    rd.compute_list_end()
    rd.submit()
    rd.sync()

    # Shader 3: add the block sums to the per-block results
    var shader3_spv = _compile(rd, "res://scan_add.glsl")
    var shader3 = rd.shader_create_from_spirv(shader3_spv)
    var pipeline3 = rd.compute_pipeline_create(shader3)
    var uniform_set3 = rd.uniform_set_create([uniform0, uniform1], shader3, 0)

    compute_list = rd.compute_list_begin()
    rd.compute_list_bind_compute_pipeline(compute_list, pipeline3)
    rd.compute_list_bind_uniform_set(compute_list, uniform_set3, 0)
    rd.compute_list_set_push_constant(compute_list, push_constant, push_constant.size())
    rd.compute_list_dispatch(compute_list, num_workgroups, 1, 1)
    rd.compute_list_end()
    rd.submit()
    rd.sync()

    var output_bytes = rd.buffer_get_data(data_buffer)
    var result = []
    var total = 0
    for i in range(n):
        var val = output_bytes.decode_u32(i * 4)
        result.append(val)

    # Total sum is prefix_sum[N-1] + input[N-1]
    total = result[n - 1] + data[n - 1]

    var output = {"count": n, "total": total, "prefix_sum": result}
    var out_file = FileAccess.open("res://output/result.json", FileAccess.WRITE)
    out_file.store_string(JSON.stringify(output))
    out_file.close()
    get_tree().quit()

func _compile(rd, path):
    var glsl = FileAccess.open(path, FileAccess.READ).get_as_text()
    return rd.shader_compile_spirv_from_source(glsl)

