        FileAccess.open(path, FileAccess.READ).get_as_text(),
        RDShaderFile.SHADER_STAGE_COMPUTE
    ))
    if shader_spirv.compile_error_compute != "":
        push_error("SPIRV error in " + path + ": " + shader_spirv.compile_error_compute)
