#define SPIRV_REFLECT_IMPLEMENTATION
#include "spirv_reflect.h"
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char** argv) {
    if (argc < 2) return 1;
    const char* path = argv[1];
    FILE* f = fopen(path, "rb");
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    unsigned char* data = malloc(size);
    fread(data, 1, size, f);
    fclose(f);

    SpvReflectShaderModule module;
    spvReflectCreateShaderModule(size, data, &module);

    uint32_t count = 0;
    spvReflectEnumerateDescriptorBindings(&module, &count, NULL);
    SpvReflectDescriptorBinding** bindings = malloc(sizeof(void*) * count);
    spvReflectEnumerateDescriptorBindings(&module, &count, bindings);

    printf("Descriptor bindings found: %u\n", count);
    for (uint32_t i = 0; i < count; i++) {
        SpvReflectDescriptorBinding* b = bindings[i];
        printf(" set=%u binding=%u name=%s type=%d\n", b->set, b->binding, b->name, (int)b->descriptor_type);
    }

    spvReflectDestroyShaderModule(&module);
    free(data);
    free(bindings);
    return 0;
}

